namespace ks{namespace{SerialTransmitPartialTest partialTest=nullptr;using T=SerialTransmitTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::RetainFirst:return{0x1104,4};case S::RetainSecond:return{0x1108,4};case S::ReadProducer:return{0x110c,6};case S::Normalize:return{0x1112,2};case S::LocateData:return{0x1114,6};case S::ResolveData:return{0x111a,2};case S::WriteData:return{0x111c,2};case S::NextProducer:return{0x111e,2};case S::MaskProducer:return{0x1120,4};case S::ReadConsumer:return{0x1124,6};case S::CompareQueue:return{0x112a,2};case S::AdmitSpace:return{0x112c,2};case S::WriteProducer:return{0x112e,6};case S::RetainCritical:return{0x1134,4};case S::MaskCritical:return{0x1138,4};case S::Enable:return{0x113c,2};case S::WriteEnable:return{0x113e,2};case S::RestoreCritical:return{0x1140,4};case S::RestoreSecond:return{0x1144,4};case S::RestoreFirst:return{0x1148,4};case S::Finish:return{0x114c,2}; default:throw std::runtime_error("Invalid serial transmit stage");}}}
bool SerialTransmitCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x1104){if(selected)throw std::runtime_error("Overlapping serial transmit");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Serial transmit capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto&v=h.regs;auto clock=[&](T::Write what){auto at=what==T::Write::Enable?0xffff8au:t.dataAddress();if(at<0x400000)return (at&1)&&h.lastwrite==int(at-1)?0u:3u;if(at>=0xfffd10&&at<0xffffa0)return (at&1)&&h.lastwrite==int(at-1)?0u:1u;return at>=0xffffa0?1u:3u;};auto cost=t.nextClocks(clock);t.advanceBefore(cost,[&](T::Read r)->uint32_t{return r==T::Read::Input?uint8_t(v[6].rl):uint16_t(h.read16(r==T::Read::Producer?0xffed6c:0xffed6e));},[&](T::Write w,uint16_t value){if(w==T::Write::Producer)f.store16(0xffed6c,int16_t(value));else f.store8(w==T::Write::Data?t.dataAddress():0xffff8a,int8_t(value));},clock);auto hold=[&](auto value){f.push(value);(**selected).depth+=sizeof(value);};auto restore=[&](auto&value){f.pop(value);(**selected).depth-=sizeof(value);};switch(stage){case S::RetainFirst:hold(v[0].er);break;case S::RetainSecond:hold(v[1].er);break;case S::ReadProducer:f.move(v[0].r,t.producer());break;case S::Normalize:v[0].er&=0xffff;value(h,v[0].er);break;case S::LocateData:f.move(v[1].er,0xffed70);break;case S::ResolveData:v[1].er=h.add32(v[1].er,v[0].er);break;case S::NextProducer:f.inc(v[0].r,1);break;case S::MaskProducer:v[0].r&=255;value(h,v[0].r);break;case S::ReadConsumer:f.move(v[1].r,t.consumer());break;case S::CompareQueue:h.sub16(v[1].r,v[0].r);break;case S::RetainCritical:v[7].er-=2;h.write16(h.exr,v[7].er);h.clockI(2);(**selected).depth+=2;break;case S::MaskCritical:h.exr=7;break;case S::Enable:f.move(v[0].rl,0xfffffff0);break;case S::RestoreCritical:h.exr=uint8_t(h.read16(v[7].er));v[7].er+=2;h.clockI(2);(**selected).depth-=2;break;case S::RestoreSecond:restore(v[1].er);break;case S::RestoreFirst:restore(v[0].er);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Serial transmit clocks differ");return true;}}

